/*TD4101 display driver*/

int BOE540x960_get_video_timings(struct mipi_dsi_dev *dev)
{
    dsih_dpi_video_t *param;

    if (dev == NULL){
        return MIPI_RET(ENODEV);
    }
    param = &dev->dpi_video;

    /* 960 x 540 | BURST | PClk 60.667MHz | ByteClk 91MHz| 24bpp */
    param->display_type = 0;
    param->no_of_lanes = 2;
    param->virtual_channel = 0;
    param->video_mode = VIDEO_BURST_WITH_SYNC_PULSES;
    param->receive_ack_packets = 0; /* enable receiving of ack packets */
    param->is_18_loosely = 0;
    param->data_en_polarity = 1;

    param->h_polarity = 0;
    param->v_polarity = 0;

    param->h_sync_pixels = 4;   /* min 4 pixels */
    param->h_back_porch_pixels = 240;
    param->v_sync_lines = 2;
    param->v_back_porch_lines = 13;
    param->color_coding = COLOR_CODE_24BIT;
    param->h_active_pixels = 540;
    param->v_active_lines = 960;
    param->h_total_pixels = 824;
    param->v_total_lines = 1219;
    param->eotp_rx_en = 0;
    param->eotp_tx_en = 1;

    param->non_continuous_clock = 1;
    param->no_of_chunks = 0;
    param->null_packet_size = 0xFFF;
    param->dpi_lp_cmd_en = 1;
    param->byte_clock = 91000; /* KHz  */
    param->pixel_clock = 60667;  /* dpi_clock */

    return 0;
}

int BOE540x960_get_command_timings(struct mipi_dsi_dev *dev)
{
    return MIPI_RET(EUNSUPPORT);
}

